export type SlideTextbookLink = {
  chapter: string;
  section: string;
  href: string;
  bridge: string;
};

export type SlideWorkedExample = {
  title: string;
  lines: string[];
};

export type DetailedSlideBeat = {
  page: number;
  title: string;
  change: string;
  explanation: string[];
  inspect: string[];
  textbook?: SlideTextbookLink;
  formula?: string;
  example?: SlideWorkedExample;
  pause?: string;
};

export type DetailedLectureChapter = {
  id: string;
  title: string;
  pages: string;
  purpose: string;
  beats: DetailedSlideBeat[];
  checkpoint: string;
};

export type DetailedLectureTutorial = {
  pdf: string;
  pageCount: number;
  estimatedTime: string;
  question: string;
  opening: string[];
  outcomes: string[];
  runningExample: {
    title: string;
    description: string;
    code: string;
  };
  chapters: DetailedLectureChapter[];
  synthesis: string[];
  finalPractice: string;
};

const book = (
  chapter: string,
  section: string,
  href: string,
  bridge: string,
): SlideTextbookLink => ({ chapter, section, href, bridge });

const beat = (
  page: number,
  title: string,
  change: string,
  explanation: string[],
  inspect: string[],
  extra: Partial<Omit<DetailedSlideBeat, "page" | "title" | "change" | "explanation" | "inspect">> = {},
): DetailedSlideBeat => ({ page, title, change, explanation, inspect, ...extra });

