          "Edge 保存 8 个引用：四条翼 hl/hr/tl/tr、两个顶点 h/t、两个面 l/r。Face.e 和 Vertex.e 分别提供面边界与顶点星的入口，其余关系通过反复跟随 Edge 字段恢复。",
