  synthesis: [
    "表示层：参数式几何用 T∘f 前向生成；隐式几何用 f∘T⁻¹ 把查询拉回旧空间。",
    "线性层：矩阵的列是基向量的去向；缩放、旋转、反射和切变都是线性映射，但非零平移不是。",
    "仿射层：齐次坐标把 Mp+t 统一进一个矩阵；点用 w=1，方向与点差用 w=0。",
    "复合层：列向量约定下最右矩阵先作用；纯平移可交换，一般旋转/平移与旋转/非均匀缩放不可交换。",
    "换轴层：复杂操作先进入方便坐标系，执行规范变换，再按逆序返回；形式是 F T F⁻¹。",
    "法线层：切线乘 M，法线乘 (M⁻¹)ᵀ 并归一化；正确性由变换后点积仍为零验证。",
    "框架层：frame-to-canonical 的列依次是局部基与原点；矩阵同时可以解释为移动几何或改变坐标表示。",
    "约束层：二维一般仿射由三个不共线点对确定，三维由四个不共面点对确定；数量够但秩不足仍不可解。",
  ],
  finalPractice: "完成 TransformWorkbench：实现 2D/3D 的 translation、scale、axis rotations、compose、inverseRigid、transformPoint、transformVector、transformNormal、frameFromAxes、frameFromPrimarySecondary、rotateAboutPivot 与 scaleAlongAxis。界面必须逐步显示乘积中每个中间状态，并提供两个顺序对照面板。测试至少覆盖：第 44-45 页零视觉变化、TR≠RT、RS≠SR、点 w=1/方向 w=0、法线与变换后切线点积为 0、pivot 固定、frame 往返为恒等、退化缩放不可逆、辅助向量近乎平行、三个共线点约束秩不足。",
