    "空间层：位置逐步去屏幕；法线与光照向量应在保持角度的共同空间计算，法线经 (M⁻¹)ᵀ 变换。",
    "剔除层：背面剔除利用封闭外向网格的几何前提，在光栅化前减少不可能可见的面，但不解决正面之间的遮挡。",
    "排序层：画家算法是遮挡 DAG 的拓扑排序；相交或循环时没有整体顺序，透明混合却仍常需要后到前。",
    "深度层：z-buffer 把排序下放到每像素，以额外深度存储换取任意图元顺序和相交几何的正确性。",
    "精度层：传统屏幕 z 在三角形上可线性插值、近处分辨率高；near/far 选择直接决定有限深度位数怎样分配。",
    "频率层：Gouraud 每顶点算光照并插值颜色；逐片元 Phong 插值法线并重新求光照，能捕获三角形内部高光。",
